-- Tracking DB Migration 005
-- Registry cleanup + tag de-poisoning (PROMPT-2, Agent 1).
--
-- A. Purge junk rows mirrored from the cleaned seed (lib/trackingSeed.ts v3):
--     - 'BTC Block %' auto-generated output labels (2,413 rows)
--     - munged BTC truncations: fake '1...'/'3...' prefixes of real bc1 wallets (484)
--     - fabricated lowercase-'t' Tron addresses (100)
--     - format-invalid addresses (8)
--     - Cardano rows (200) — chain is not tracked by NOVRIX
--     - 'New Entity %' fabricated TOP_ENTITIES (21 entities, random categories)
-- B. Tag de-poisoning: LABELS-map rows were all seeded with tags='exchange';
--    recompute tags by label content (mirrors tagForLabel() in trackingSeed.ts).
-- Idempotent: safe to re-run. Apply with:
--   npx wrangler d1 execute novrix-tracking-db --remote --file=database/migrations/tracking/005_registry_cleanup_expansion.sql

-- ─── A1. Pattern purges ──────────────────────────────────────────────────────
DELETE FROM known_addresses WHERE label LIKE 'BTC Block %';
DELETE FROM known_addresses WHERE blockchain = 'Cardano';
-- fabricated Tron: real Tron addresses start uppercase 'T' (LIKE is case-sensitive)
DELETE FROM known_addresses WHERE blockchain = 'Tron' AND address LIKE 't%';
DELETE FROM known_addresses WHERE entity LIKE 'New Entity %';
DELETE FROM entity_holdings WHERE entity LIKE 'New Entity %';

-- ─── A2. Explicit purges (3,005 addresses: munged truncations, format-invalid,
