-- ─── B. Tag de-poisoning (order: defi before exchange — 'Stargate' contains 'Gate') ──
UPDATE known_addresses SET tags = 'defi'
  WHERE tags = 'exchange' AND (
    label LIKE '%Uniswap%' OR label LIKE '%MakerDAO%' OR label LIKE '%Curve%'
    OR label LIKE '%Aave%' OR label LIKE '%Compound%' OR label LIKE '%Lido%'
    OR label LIKE '%Bridge%' OR label LIKE '%Router%' OR label LIKE '%Stargate%'
    OR label LIKE '%LayerZero%');
UPDATE known_addresses SET tags = 'mm'
  WHERE tags = 'exchange' AND label LIKE '%MEV Bot%';
UPDATE known_addresses SET tags = 'miner'
  WHERE tags = 'exchange' AND (
    label LIKE '%Mining%' OR label LIKE '%Pool%' OR label LIKE '%Foundry%'
    OR label LIKE '%AntPool%' OR label LIKE '%F2Pool%' OR label LIKE '%ViaBTC%'
    OR label LIKE '%MARA%' OR label LIKE '%Riot%');
UPDATE known_addresses SET tags = 'stablecoin'
  WHERE tags = 'exchange' AND (
    label LIKE '%Tether%' OR label LIKE '%Circle%' OR label LIKE '%Treasury%');
UPDATE known_addresses SET tags = 'whale'
  WHERE tags = 'exchange' AND (
    label LIKE '%Whale%' OR label LIKE '%Rich List%');
-- Everything left tagged 'exchange' at this point genuinely matches an exchange name
-- (Binance/Coinbase/Kraken/Bitfinex/OKX/Bybit/Huobi/KuCoin/Gate/Poloniex/FTX/
--  Bitstamp/Gemini/Crypto.com/Upbit/Bithumb).

